import React from 'react';
import { Box, Typography, Button } from '@mui/material';

function CustomCard({ title, description, tags, buttonText, imageUrl }) {
  return (
    <Box
      sx={{
        width: '328px',
        height: '519px',
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'center',
        alignItems: 'center',
        padding: 0,
        backgroundColor: '#FFFFFF',
        border: '1px solid #293349',
        borderRadius: '16px 16px 0 0',
        boxSizing: 'border-box',
        margin: '10px',  // Kartlar arasına boşluk eklemek için margin ekledik
      }}
    >
      <Box
        sx={{
          display: 'flex',
          flexDirection: 'row',
          justifyContent: 'flex-end',
          alignItems: 'flex-start',
          padding: '16px',
          gap: '10px',
          width: '328px',
          height: '171px',
          backgroundImage: `url(${imageUrl})`,
        }}
      >
        <Box
          sx={{
            display: 'flex',
            justifyContent: 'center',
            alignItems: 'center',
            padding: '8px',
            width: '36px',
            height: '36px',
            backgroundColor: '#F6F8FF',
            borderRadius: '100px',
          }}
        >
          <Box sx={{ width: '20px', height: '20px' }} />
        </Box>
      </Box>

      <Box
        sx={{
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          padding: '16px',
          gap: '16px',
          width: '328px',
          height: '348px',
        }}
      >
        <Box sx={{ display: 'flex', flexDirection: 'column', alignItems: 'flex-start', width: '296px', gap: '16px' }}>
          <Typography variant="h6" sx={{ fontWeight: '500', fontSize: '20px', color: '#1D1D1D' }}>
            {title}
          </Typography>
          <Typography sx={{ fontSize: '16px', color: '#878787' }}>
            {description}
          </Typography>
        </Box>

        <Box
          sx={{
            display: 'flex',
            flexDirection: 'row',
            justifyContent: 'center',
            alignItems: 'center',
            gap: '8px',
            width: '296px',
            height: '22px',
          }}
        >
          {tags.map((tag, index) => (
            <Box
              key={index}
              sx={{
                display: 'flex',
                justifyContent: 'center',
                alignItems: 'center',
                padding: '4px 8px',
                width: '34px',
                height: '22px',
                border: '1px solid #293349',
                borderRadius: '16px',
              }}
            >
              <Typography sx={{ fontSize: '12px', color: '#293349' }}>{tag}</Typography>
            </Box>
          ))}
        </Box>

        <Box sx={{ display: 'flex', flexDirection: 'row', justifyContent: 'center', alignItems: 'center', gap: '8px', width: '296px', height: '48px' }}>
          <Button variant="contained" sx={{ backgroundColor: '#00C26D', borderRadius: '4px', padding: '4px 52px', color: '#FFFFFF' }}>
            {buttonText}
          </Button>
        </Box>
      </Box>
    </Box>
  );
}

export default CustomCard;
